<script setup>
import {ref,onMounted,watch} from 'vue';import {api,ui} from '../lib/api.js';import {money,dateLabel,progress,paid,downloadCsv,today} from '../lib/format.js';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import RevenueChart from '../components/RevenueChart.vue';import EmptyState from '../components/EmptyState.vue';
const data=ref(null),error=ref(''),period=ref(localStorage.getItem('bw-period')||'year'),from=ref(today().slice(0,4)+'-01-01'),to=ref(today());
async function load(){try{error.value='';data.value=await api(`/dashboard?period=${period.value}&from=${from.value}&to=${to.value}`);}catch(e){error.value=e.message;}}
watch([period,from,to,()=>ui.revision],()=>{localStorage.setItem('bw-period',period.value);load();});onMounted(load);
function exportData(){downloadCsv('birostweb-encaissements.csv',['Période','Encaissements EUR','Dépenses payées EUR'],data.value.chart.map(r=>[r.key,(r.revenue/100).toFixed(2),(r.expenses/100).toFixed(2)]));}
</script>
<template><PageTitle number="01" title="VUE D’ENSEMBLE" subtitle="Votre activité, sous tous les angles."><RouterLink class="btn primary" to="/quotes/new"><Icon name="Plus"/>Créer un devis<Icon name="ArrowUpRight"/></RouterLink></PageTitle><p v-if="error" class="form-error">{{error}} <button class="text-button" @click="load">Réessayer</button></p><div v-if="!data&&!error" class="skeleton-page" aria-label="Chargement"></div><template v-if="data"><div class="overview-strip"><div><span class="live-dot"></span><span>Le studio en mouvement</span></div><span class="mono">{{new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'})}}</span></div><section class="kpi-grid"><article class="kpi hero-kpi"><div class="kpi-label">CA FACTURÉ DU MOIS <Icon name="ArrowUpRight"/></div><div class="kpi-value">{{money(data.stats.monthlyRevenue)}}<span class="kpi-corner">HT</span></div><div class="kpi-foot"><span class="small-dot"></span>{{money(data.stats.monthlyCollected)}} encaissés ce mois</div></article><article class="kpi"><div class="kpi-label">RESTE À ENCAISSER <Icon name="Wallet"/></div><div class="kpi-value">{{money(data.stats.remaining)}}</div><div class="kpi-foot"><span class="accent">{{data.stats.pendingInvoices}} factures</span> en attente de paiement</div></article><article class="kpi"><div class="kpi-label">PROJETS EN COURS <Icon name="FolderKanban"/></div><div class="kpi-value">{{String(data.stats.activeProjects).padStart(2,'0')}}<span class="kpi-slash">/</span><span class="kpi-minor">{{String(data.stats.completedProjects).padStart(2,'0')}}</span></div><div class="kpi-foot">En cours <span class="muted">/ terminés & livrés</span></div></article><article class="kpi"><div class="kpi-label">REVENU RÉCURRENT <Icon name="RefreshCw"/></div><div class="kpi-value">{{money(data.stats.mrr)}}<span class="kpi-corner">/mois</span></div><div class="kpi-foot">{{data.subscriptions.length}} abonnements <span class="muted">· {{money(data.stats.arr)}} / an estimés</span></div></article></section><div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-head"><div><span class="eyebrow">01 — FINANCES</span><h2>LES CHIFFRES PARLENT.</h2></div><button class="icon-button outlined" title="Exporter le graphique en CSV" aria-label="Exporter les encaissements" @click="exportData"><Icon name="Download"/></button></div><div class="chart-controls"><div><strong>{{money(data.stats.collected)}}</strong><span class="muted"> encaissés sur la période</span></div><div class="segmented"><button v-for="[v,l] in [['7d','7 J'],['30d','30 J'],['3m','3 MOIS'],['year','ANNÉE'],['custom','…']]" :key="v" :class="{selected:period===v}" @click="period=v" :aria-label="v==='custom'?'Période personnalisée':l">{{l}}</button></div></div><div class="custom-dates" v-if="period==='custom'"><label>Du<input type="date" v-model="from"></label><label>Au<input type="date" v-model="to"></label></div><RevenueChart :rows="data.chart"/><div class="chart-legend"><span><i class="legend-accent"></i>Encaissements TTC</span><span><i class="legend-muted"></i>Dépenses payées TTC</span><span class="chart-total">CA annuel facturé : <b>{{money(data.stats.annualRevenue)}} HT</b></span></div></section><section class="attention-panel"><div class="panel-head"><div><span class="eyebrow">02 — À SUIVRE</span><h2>LE BON TIMING.</h2></div><span class="slash-mark">///</span></div><div v-if="!data.upcoming.length" class="dark-empty">Tout est à jour.<br>Place aux projets.</div><RouterLink v-for="e in data.upcoming.slice(0,4)" :key="e.id" :to="e.type==='subscriptions'?'/finances':`/${e.type}/${e.entityId}`" class="deadline"><div class="deadline-date" :class="{late:e.date<today()}"><strong>{{e.date.slice(-2)}}</strong><span>{{new Date(e.date+'T12:00:00Z').toLocaleDateString('fr-FR',{month:'short'})}}</span></div><div class="deadline-info"><strong>{{e.title}}</strong><small>{{e.date<today()?'En retard · ':''}}{{e.detail}}</small></div><Icon name="ArrowUpRight" :size="16"/></RouterLink><RouterLink class="attention-link" to="/calendar">Tout le calendrier<Icon name="ArrowUpRight"/></RouterLink></section></div><div class="dashboard-bottom"><section class="panel project-panel"><div class="panel-head"><div><span class="eyebrow">03 — PRODUCTION</span><h2>LES PROJETS AVANCENT.</h2></div><RouterLink class="text-button" to="/projects">Tous les projets<Icon name="ArrowUpRight" :size="16"/></RouterLink></div><div class="table-scroll"><table><thead><tr><th>PROJET / CLIENT</th><th>STATUT</th><th>AVANCEMENT</th><th class="text-right">RESTE À PAYER</th><th></th></tr></thead><tbody><tr v-for="p in data.projects" :key="p.id"><td><RouterLink class="table-title" :to="`/projects/${p.id}`">{{p.title}}</RouterLink><div class="table-sub">{{p.client.name}}</div></td><td><Badge :status="p.status"/></td><td><div class="progress-cell"><div class="progress-track"><i :style="{width:progress(p)+'%'}"></i></div><span>{{progress(p)}}%</span></div></td><td class="text-right mono">{{money(p.totalCents-paid(p))}}</td><td><RouterLink :to="`/projects/${p.id}`" class="icon-button" :aria-label="`Ouvrir ${p.title}`"><Icon name="ArrowUpRight"/></RouterLink></td></tr></tbody></table></div><EmptyState v-if="!data.projects.length" title="Le prochain projet commence ici." description="Convertissez un devis accepté pour ouvrir son dossier."/></section><section class="panel activity-panel"><div class="panel-head"><div><span class="eyebrow">04 — FIL DU STUDIO</span><h2>DERNIERS MOUVEMENTS.</h2></div></div><ol class="activity-list"><li v-for="a in data.activity.slice(0,5)" :key="a.id"><i></i><div><RouterLink :to="['quotes','projects','invoices','clients'].includes(a.entity)?`/${a.entity}/${a.entityId}`:'/'">{{a.action}}</RouterLink><small>{{dateLabel(a.createdAt,true)}} · {{new Date(a.createdAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}}</small></div></li></ol><p class="muted" v-if="!data.activity.length">Les prochaines actions apparaîtront ici.</p></section></div><div class="overview-footer"><span class="mono">MOINS D’ADMIN. PLUS DE CRÉATION.</span><span class="slash-mark">///</span></div></template></template>
